import json,os,subprocess,tempfile
s=json.loads(subprocess.check_output(['tailscale','status','--json'],timeout=8));p=next(x for x in s['Peer'].values() if x.get('HostName')=='xavier')
keys=p.get('sshHostKeys') or []
if not p.get('Online') or not p.get('TailscaleIPs') or not keys:raise SystemExit('identity or connectivity unavailable')
with tempfile.TemporaryDirectory(prefix='awai156-hostkeys-') as d:
 f=os.path.join(d,'known_hosts')
 with open(f,'x') as out:
  os.chmod(f,0o600)
  for key in keys:
   assert key.startswith(('ssh-ed25519 ','ssh-rsa ','ecdsa-sha2-nistp256 ')) and '\n' not in key
   out.write('xavier '+key+'\n')
 remote='/usr/bin/python3 -c \'import subprocess,uuid,json,tempfile,pathlib,socket,threading\nunit="awai156-http-"+uuid.uuid4().hex+".service";out={}\nwith tempfile.TemporaryDirectory(prefix="awai156-test-") as d:\n root=pathlib.Path(d);sock=str(root/"peer.sock");req=root/"request.json";response=root/"response.json";req.write_text("{\\"test\\":true}");expected=b"{\\"ok\\":true}";server=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);server.settimeout(8);server.bind(sock);server.listen(1);peer={}\n def run_peer():\n  try:\n   c,_=server.accept();c.settimeout(4);data=b""\n   while b"\\r\\n\\r\\n" not in data and len(data)<8192:data+=c.recv(1024)\n   headers,body=data.split(b"\\r\\n\\r\\n",1);length=0\n   for line in headers.split(b"\\r\\n"):\n    if line.lower().startswith(b"content-length:"):length=int(line.split(b":",1)[1].strip())\n   while len(body)<length and len(body)<8192:body+=c.recv(1024)\n   peer["body_matches"]=body==b"{\\"test\\":true}";c.sendall(b"HTTP/1.1 200 OK\\r\\nContent-Type: application/json\\r\\nContent-Length: "+str(len(expected)).encode()+b"\\r\\nConnection: close\\r\\n\\r\\n"+expected);c.close()\n  except Exception as e:peer["error"]=type(e).__name__\n t=threading.Thread(target=run_peer);t.start()\n cmd=["/usr/bin/systemd-run","--user","--quiet","--wait","--collect","--pipe","--unit="+unit,"--property=Type=oneshot","--property=NoNewPrivileges=yes","--property=LimitAS=128M","--property=LimitCPU=3s","--property=TimeoutStartSec=8s","/usr/bin/curl","--disable","--http1.1","--noproxy","*","--unix-socket",sock,"-fsS","--connect-timeout","2","--max-time","4","--header","Content-Type: application/json","--data-binary","@"+str(req),"--output",str(response),"http://localhost/v1/chat/completions"]\n try:\n  r=subprocess.run(cmd,capture_output=True,text=True,timeout=10);out.update(exit=r.returncode,stderr_nonempty=bool(r.stderr),response_matches=response.exists() and response.read_bytes()==expected)\n except subprocess.TimeoutExpired:out["status"]="command-timeout"\n finally:\n  q=subprocess.run(["/usr/bin/systemctl","--user","show",unit,"-p","LoadState","-p","ActiveState"],capture_output=True,text=True,timeout=5);out["after"]=q.stdout.strip().splitlines()\n  if "ActiveState=active" in out["after"] or "ActiveState=activating" in out["after"]:\n   z=subprocess.run(["/usr/bin/systemctl","--user","stop",unit],capture_output=True,text=True,timeout=5);out["cleanup_stop_exit"]=z.returncode\n   q=subprocess.run(["/usr/bin/systemctl","--user","show",unit,"-p","LoadState","-p","ActiveState"],capture_output=True,text=True,timeout=5);out["after_cleanup"]=q.stdout.strip().splitlines()\n  t.join(timeout=9);server.close();out["peer"]=peer;out["peer_thread_alive"]=t.is_alive()\nprint(json.dumps(out))\''
 cmd=['ssh','-o','BatchMode=yes','-o','ConnectTimeout=6','-o','StrictHostKeyChecking=yes','-o','HostKeyAlias=xavier','-o','UserKnownHostsFile='+f,'-o','GlobalKnownHostsFile=/dev/null','-o','HostName='+p['TailscaleIPs'][0],'xavier@xavier',remote]
 try:
  r=subprocess.run(cmd,stdin=subprocess.DEVNULL,capture_output=True,text=True,timeout=12)
  t=r.stderr.lower();status='success' if r.returncode==0 else 'host-key-mismatch' if 'host key verification failed' in t or 'remote host identification has changed' in t else 'authentication-denied' if 'permission denied' in t else 'unavailable'
  print('status',status,'exit',r.returncode)
  if r.returncode==0:print(r.stdout.strip())
 except subprocess.TimeoutExpired:print('status timeout')
